INSERT INTO `contenidos` (`id_contenido`, `seccion`, `titulo`, `cuerpo`, `archivo`, `tipo_mime`, `enlace`, `orden`, `activo`, `id_admin`, `created_at`, `updated_at`) VALUES (10,'banner','Banner principal','Viviendas y galpones en madera, fabricados en serie','img/hero-panoramica.jpg','image/jpeg',NULL,1,1,1,'2026-11-16 05:32:51','2026-11-16 05:32:51');
INSERT INTO `contenidos` (`id_contenido`, `seccion`, `titulo`, `cuerpo`, `archivo`, `tipo_mime`, `enlace`, `orden`, `activo`, `id_admin`, `created_at`, `updated_at`) VALUES (11,'faq','¿Qué madera utilizan en sus productos?','Pino radiata con tratamiento de impregnación Vacío-Presión. El preservante penetra en la madera y la protege contra hongos e insectos, lo que alarga su vida útil en uso estructural y a la intemperie.',NULL,NULL,NULL,1,1,1,'2026-11-16 05:32:51','2026-11-16 05:32:51');
INSERT INTO `contenidos` (`id_contenido`, `seccion`, `titulo`, `cuerpo`, `archivo`, `tipo_mime`, `enlace`, `orden`, `activo`, `id_admin`, `created_at`, `updated_at`) VALUES (12,'faq','¿Qué son los conectores metálicos y cuándo se usan?','Son placas y piezas de acero galvanizado que unen cerchas, entramados de muro y secciones prefabricadas. Se dimensionan según el cálculo estructural de cada proyecto, no se despachan como artículo suelto.',NULL,NULL,NULL,2,1,1,'2026-11-16 05:32:51','2026-11-16 05:32:51');
INSERT INTO `contenidos` (`id_contenido`, `seccion`, `titulo`, `cuerpo`, `archivo`, `tipo_mime`, `enlace`, `orden`, `activo`, `id_admin`, `created_at`, `updated_at`) VALUES (13,'faq','¿Trabajan con viviendas industrializadas y proyectos DS19?','Sí. Fabricamos panelería y volumetría prefabricada para conjuntos habitacionales, incluida la línea DS19, con montaje en terreno coordinado con la constructora.',NULL,NULL,NULL,3,1,1,'2026-11-16 05:32:51','2026-11-16 05:32:51');
INSERT INTO `contenidos` (`id_contenido`, `seccion`, `titulo`, `cuerpo`, `archivo`, `tipo_mime`, `enlace`, `orden`, `activo`, `id_admin`, `created_at`, `updated_at`) VALUES (14,'faq','¿Hacen despachos fuera de la Región Metropolitana?','Sí. Tenemos obras entregadas en las regiones Metropolitana, del Maule, del Biobío y de La Araucanía. El plazo y el costo de traslado se confirman al cotizar según destino y volumen.',NULL,NULL,NULL,4,1,1,'2026-11-16 05:32:51','2026-11-16 05:32:51');
INSERT INTO `contenidos` (`id_contenido`, `seccion`, `titulo`, `cuerpo`, `archivo`, `tipo_mime`, `enlace`, `orden`, `activo`, `id_admin`, `created_at`, `updated_at`) VALUES (15,'faq','¿Qué normativa cumplen sus productos?','La madera estructural se rige por NCh 1198 y los conectores se especifican bajo criterios ANSI/TPI. Las certificaciones vigentes y sus organismos están publicadas en la sección Certificaciones de este sitio.',NULL,NULL,NULL,5,1,1,'2026-11-16 05:32:51','2026-11-16 05:32:51');
INSERT INTO `contenidos` (`id_contenido`, `seccion`, `titulo`, `cuerpo`, `archivo`, `tipo_mime`, `enlace`, `orden`, `activo`, `id_admin`, `created_at`, `updated_at`) VALUES (16,'faq','¿Cómo solicito una cotización?','Complete el formulario de contacto con los datos de su proyecto. Recibirá un correo de confirmación con su número de seguimiento y el equipo comercial revisará el requerimiento para responderle.',NULL,NULL,NULL,6,1,1,'2026-11-16 05:32:51','2026-11-16 05:32:51');
